(function() {
    'use strict';

    class HotelPacificoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Pricing Power: Dynamic Revenue Management';
            this.version = '1.1.0';
            this.CAPACITY = 240;
            this.FIXED_COSTS = 18000;
            this.VAR_COST_PER_ROOM = 25;
            this.OTA_COMMISSION = 0.22;
            this.DIRECT_COMMISSION = 0.02;

            this.ROUNDS = [
                {
                    id: 1,
                    scenarioName_en: 'February — Low Season',
                    scenarioName_es: 'Febrero — Baja Temporada',
                    briefing_en: 'Calibration round. Market demand is subdued. This is your opportunity to learn segment behavior before peak periods. Metropolis is holding firm at $145. Conecta sits at $105 targeting budget leisure travelers.',
                    briefing_es: 'Ronda de calibracion. La demanda del mercado es moderada. Esta es su oportunidad de entender el comportamiento de los segmentos antes de las temporadas altas. Metropolis mantiene $145. Conecta esta en $105 apuntando al ocio economico.',
                    baseDemandLeisure: 90,
                    refRateLeisure: 100,
                    baseDemandBusiness: 50,
                    refRateBusiness: 180,
                    noShowRate: 0.08,
                    compRates: { metropolis: 145, conecta: 105, suites: 90 }
                },
                {
                    id: 2,
                    scenarioName_en: 'April — Shoulder Season',
                    scenarioName_es: 'Abril — Temporada Hombro',
                    briefing_en: 'Corporate demand is rising. A key corporate account is up for annual renegotiation. Conecta launched a promotional rate of $85 targeting OTA leisure travelers. Watch for segment leakage between leisure and business bookings.',
                    briefing_es: 'La demanda corporativa esta aumentando. Una cuenta corporativa ancla esta en renegociacion anual. Conecta lanzo una tarifa promocional de $85 orientada al ocio OTA. Ojo con la fuga de segmentos entre reservas leisure y corporativas.',
                    baseDemandLeisure: 110,
                    refRateLeisure: 110,
                    baseDemandBusiness: 100,
                    refRateBusiness: 190,
                    noShowRate: 0.07,
                    compRates: { metropolis: 160, conecta: 85, suites: 95 }
                },
                {
                    id: 3,
                    scenarioName_en: 'July — Peak High Season',
                    scenarioName_es: 'Julio — Pico Temporada Alta',
                    briefing_en: 'Major international event in the city is driving leisure demand to peak levels. Conecta launched an aggressive flash sale at $99. Demand exceeds your capacity — protect inventory for high-yield late bookings. Do NOT follow Conecta into a price war.',
                    briefing_es: 'Un gran evento internacional esta llevando la demanda de ocio a niveles maximos. Conecta lanzo un flash sale agresivo a $99. La demanda supera su capacidad: proteja inventario para reservas tardias de alto rendimiento. NO siga a Conecta en una guerra de precios.',
                    baseDemandLeisure: 200,
                    refRateLeisure: 130,
                    baseDemandBusiness: 70,
                    refRateBusiness: 200,
                    noShowRate: 0.06,
                    compRates: { metropolis: 195, conecta: 99, suites: 120 }
                },
                {
                    id: 4,
                    scenarioName_en: 'November — Holiday Weekend',
                    scenarioName_es: 'Noviembre — Fin de Semana Festivo',
                    briefing_en: 'Maximum demand pressure. Metropolis is fully booked at $230. Your overbooking decision is critical — the no-show rate is only 5% this period. An aggressive overbooking strategy risks costly walk events and severe GSS penalties that carry into Period 5.',
                    briefing_es: 'Presion de demanda maxima. Metropolis esta completo a $230. Su decision de overbooking es critica: la tasa de no-shows es solo del 5% este periodo. Un overbooking agresivo arriesga eventos de walk costosos y penalizaciones severas de GSS que afectaran el Periodo 5.',
                    baseDemandLeisure: 230,
                    refRateLeisure: 150,
                    baseDemandBusiness: 90,
                    refRateBusiness: 220,
                    noShowRate: 0.05,
                    compRates: { metropolis: 230, conecta: 140, suites: 130 }
                },
                {
                    id: 5,
                    scenarioName_en: 'December — Year-End Strategy',
                    scenarioName_es: 'Diciembre — Revision Estrategica',
                    briefing_en: 'Soft season with active corporate market for year-end closings. GSS scores from prior periods now influence demand pace via loyalty premium. Your final CRI score determines the Year 2 mandate from PE owners.',
                    briefing_es: 'Temporada suave con mercado corporativo activo para cierres de ano. Las puntuaciones GSS de periodos anteriores ahora influyen en la demanda via prima de fidelidad. Su CRI final determina el mandato del Ano 2 ante los propietarios de capital privado.',
                    baseDemandLeisure: 80,
                    refRateLeisure: 100,
                    baseDemandBusiness: 110,
                    refRateBusiness: 170,
                    noShowRate: 0.09,
                    compRates: { metropolis: 140, conecta: 90, suites: 85 }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    gss: 85,
                    totalRevPAR: 0,
                    totalNetRevPAR: 0,
                    totalCRI: 0,
                    revparHistory: [],
                    occHistory: [],
                    adrHistory: [],
                    gssHistory: [],
                    netRevparHistory: [],
                    walkEvents: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    tarifaLeisure: 100,
                    tarifaBusiness: 180,
                    limiteEarly: 40,
                    overbookingPct: 5,
                    canalOtaPct: 45
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var tlInput = document.getElementById('tarifaLeisureInput');
            var tbInput = document.getElementById('tarifaBusinessInput');
            var leInput = document.getElementById('limiteEarlyInput');
            var obInput = document.getElementById('overbookingInput');
            var otaInput = document.getElementById('canalOtaInput');

            if (tlInput) decisions.tarifaLeisure = parseFloat(tlInput.value);
            if (tbInput) decisions.tarifaBusiness = parseFloat(tbInput.value);
            if (leInput) decisions.limiteEarly = parseInt(leInput.value);
            if (obInput) decisions.overbookingPct = parseInt(obInput.value);
            if (otaInput) decisions.canalOtaPct = parseInt(otaInput.value);

            if (!decisions.tarifaLeisure || decisions.tarifaLeisure < 50 || decisions.tarifaLeisure > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_tarifa_leisure'), 'warning'
                );
                return false;
            }
            if (!decisions.tarifaBusiness || decisions.tarifaBusiness < 80 || decisions.tarifaBusiness > 400) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_tarifa_business'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var periodIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[periodIdx];

            var gssMultiplier = 1 + (ds.gss - 85) * 0.005;

            var epsilonLeisure = 2.5;
            var leisureDemand = Math.round(
                round.baseDemandLeisure * gssMultiplier *
                Math.pow(round.refRateLeisure / d.tarifaLeisure, epsilonLeisure)
            );

            var epsilonBusiness = 0.8;
            var businessDemand = Math.round(
                round.baseDemandBusiness * gssMultiplier *
                Math.pow(round.refRateBusiness / d.tarifaBusiness, epsilonBusiness)
            );

            var earlyRooms = Math.round(this.CAPACITY * d.limiteEarly / 100);
            var lateRooms = this.CAPACITY - earlyRooms;
            var maxAccepted = Math.round(this.CAPACITY * (1 + d.overbookingPct / 100));

            var leisureSold = Math.min(leisureDemand, earlyRooms);
            var businessSold = Math.min(businessDemand, Math.min(lateRooms, maxAccepted - leisureSold));
            var totalAccepted = leisureSold + businessSold;

            var noShows = Math.round(totalAccepted * round.noShowRate);
            var actualOccupied = totalAccepted - noShows;
            var walkCount = Math.max(0, actualOccupied - this.CAPACITY);
            var roomsOccupied = Math.min(actualOccupied, this.CAPACITY);
            var occupancyRate = roomsOccupied / this.CAPACITY;

            var otaFraction = d.canalOtaPct / 100;
            var directFraction = 1 - otaFraction;
            var leisureNetRate = d.tarifaLeisure * (
                directFraction * (1 - this.DIRECT_COMMISSION) +
                otaFraction * (1 - this.OTA_COMMISSION)
            );
            var businessOtaFraction = otaFraction * 0.3;
            var businessDirectFraction = 1 - businessOtaFraction;
            var businessNetRate = d.tarifaBusiness * (
                businessDirectFraction * (1 - this.DIRECT_COMMISSION) +
                businessOtaFraction * (1 - this.OTA_COMMISSION)
            );

            var grossRevenue = (leisureSold * d.tarifaLeisure) + (businessSold * d.tarifaBusiness);
            var netRevenue = (leisureSold * leisureNetRate) + (businessSold * businessNetRate);
            var variableCosts = roomsOccupied * this.VAR_COST_PER_ROOM;
            var totalCosts = this.FIXED_COSTS + variableCosts;
            var walkPenaltyCost = walkCount * d.tarifaBusiness * 1.5;
            var operatingProfit = netRevenue - totalCosts - walkPenaltyCost;

            var revpar = grossRevenue / this.CAPACITY;
            var netRevpar = (netRevenue - variableCosts) / this.CAPACITY;
            var adr = roomsOccupied > 0 ? grossRevenue / roomsOccupied : 0;

            var marketAvgRate = (round.compRates.metropolis + round.compRates.conecta + round.compRates.suites) / 3;
            var marketAvgOcc = 0.72;
            var marketRevPAR = marketAvgRate * marketAvgOcc;
            var rgi = marketRevPAR > 0 ? revpar / marketRevPAR : 1;

            var gssChange = 0;
            if (walkCount > 0) gssChange -= walkCount * 3;
            if (walkCount === 0 && occupancyRate > 0.8) gssChange += 2;
            if (d.tarifaLeisure > round.compRates.metropolis * 1.1) gssChange -= 1;
            var newGSS = Math.max(40, Math.min(100, ds.gss + gssChange));

            var priceWarTriggered = d.tarifaLeisure < round.compRates.conecta;
            var marketDilutionNote = '';
            if (priceWarTriggered) {
                marketDilutionNote = '<br>&#9888; <strong>' + window.mySimulation.t('warn_price_war') + '</strong>';
            }

            var spoilageRooms = Math.max(0, this.CAPACITY - roomsOccupied);

            var revparScore  = Math.min(100, (revpar / 150) * 100) * 0.40;
            var netRevparScore = Math.min(100, (netRevpar / 80) * 100) * 0.20;
            var rgiScore = Math.min(100, rgi * 100) * 0.20;
            var gssScore = (newGSS / 100) * 100 * 0.20;
            var cri = revparScore + netRevparScore + rgiScore + gssScore;

            ds.gss = newGSS;
            ds.totalRevPAR += revpar;
            ds.totalNetRevPAR += netRevpar;
            ds.totalCRI += cri;
            // --- v1.1.0 fix: persist gradebook composite (running avg CRI) every period ---
            ds.performance = ds.performance || {};
            ds.performance.overallScore = Math.round(ds.totalCRI / (state.currentPeriod || 1));
            ds.performance.score = ds.performance.overallScore;
            ds.walkEvents += walkCount;
            ds.revparHistory.push(Math.round(revpar * 100) / 100);
            ds.occHistory.push(Math.round(occupancyRate * 1000) / 10);
            ds.adrHistory.push(Math.round(adr * 100) / 100);
            ds.gssHistory.push(newGSS);
            ds.netRevparHistory.push(Math.round(netRevpar * 100) / 100);

            var t = window.mySimulation.t.bind(window.mySimulation);
            var log = '';
            log += '&#127968; <strong>' + t('log_rooms_sold') + ':</strong> ' + roomsOccupied + ' / 240 (' + Math.round(occupancyRate * 100) + '%)';
            log += '<br>&#128181; <strong>' + t('log_leisure_sold') + ':</strong> ' + leisureSold + ' @ $' + d.tarifaLeisure;
            log += '<br>&#128188; <strong>' + t('log_business_sold') + ':</strong> ' + businessSold + ' @ $' + d.tarifaBusiness;
            log += '<br>&#128200; <strong>' + t('log_gross_rev') + ':</strong> $' + Math.round(grossRevenue).toLocaleString();
            log += '<br>&#128200; <strong>' + t('log_net_rev') + ':</strong> $' + Math.round(netRevenue).toLocaleString();
            log += '<br>&#128201; <strong>RevPAR:</strong> $' + revpar.toFixed(2);
            log += '<br>&#128201; <strong>Net RevPAR:</strong> $' + netRevpar.toFixed(2);
            log += '<br>&#128201; <strong>ADR:</strong> $' + adr.toFixed(2);
            log += '<br>&#127758; <strong>RevPAR Index (RGI):</strong> ' + (rgi * 100).toFixed(1) + '%';
            if (walkCount > 0) {
                log += '<br>&#128683; <strong>' + t('log_walk_events') + ':</strong> ' + walkCount + ' ' + t('log_guests') + ' — $' + Math.round(walkPenaltyCost).toLocaleString() + ' ' + t('log_compensation');
            }
            if (noShows > 0) {
                log += '<br>&#128123; <strong>' + t('log_no_shows') + ':</strong> ' + noShows;
            }
            if (spoilageRooms > 0) {
                log += '<br>&#10060; <strong>' + t('log_spoilage') + ':</strong> ' + spoilageRooms + ' habs.';
            }
            log += '<br>&#128522; <strong>GSS:</strong> ' + newGSS + (gssChange >= 0 ? ' (+' + gssChange + ')' : ' (' + gssChange + ')');
            log += '<br>&#127942; <strong>CRI:</strong> ' + cri.toFixed(1) + '/100';
