        getPerformanceSummary(history) {
            if (!history.length) return {};
            var revpars = history.map(function(r) { return r.results ? (r.results.revpar || 0) : 0; });
            var totalRevPAR = revpars.reduce(function(s, v) { return s + v; }, 0);
            var avgRevPAR = totalRevPAR / revpars.length;
            var cris = history.map(function(r) { return r.results ? (r.results.cri || 0) : 0; });
            var avgCRI = cris.reduce(function(s, v) { return s + v; }, 0) / cris.length;
            var lastResult = history[history.length - 1];
            var finalGSS = lastResult && lastResult.results ? (lastResult.results.gss || 85) : 85;
            var walkTotal = history.reduce(function(s, r) { return s + (r.results ? (r.results.walkCount || 0) : 0); }, 0);

            var performance = 'Principiante';
            var insights = [];
            if (avgCRI >= 70 && finalGSS >= 80 && walkTotal === 0) {
                performance = 'Excelente — Revenue Manager Estrategico';
                insights = ['Excelente balance entre RevPAR, Net RevPAR y satisfaccion de huespedes.', 'Superaste al conjunto competitivo en la mayoria de las temporadas.'];
            } else if (avgCRI >= 55) {
                performance = 'Competente — Gestor de Yield Solido';
                insights = ['Buen desempeno general. Revisa la asignacion de inventario y el mix de canales para mejorar el Net RevPAR.'];
            } else {
                performance = 'En Desarrollo — Revenue Management Basico';
                insights = ['Considera estrategias de proteccion de inventario y evita la dependencia excesiva de OTAs.', 'Recuerda: RevPAR = ADR x Ocupacion. Equilibrar ambas es clave.'];
            }
            if (walkTotal > 3) {
                insights.push('Los eventos de walk daniaron el GSS. Calibra el overbooking segun la tasa de no-show del periodo.');
            }

            var _tier = (avgCRI >= 70 && finalGSS >= 80 && walkTotal === 0) ? 'excellent'
                      : (avgCRI >= 55) ? 'competent' : 'developing';
            var _tt = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var _performanceLabel = _tt('grade_' + _tier);
            var _locIns = (_tier === 'excellent') ? [_tt('insight_exc_1'), _tt('insight_exc_2')]
                        : (_tier === 'competent') ? [_tt('insight_comp_1')]
                        : [_tt('insight_dev_1'), _tt('insight_dev_2')];
            if (walkTotal > 3) { _locIns.push(_tt('insight_walk')); }
            insights = _locIns;
            var _overall = Math.round(avgCRI);
            return {
                avgRevPAR: avgRevPAR,
                avgCRI: avgCRI,
                overallScore: _overall,
                score: _overall,
                finalGSS: finalGSS,
                walkTotal: walkTotal,
                performance: performance,
                performanceLabel: _performanceLabel,
                tier: _tier,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
